### `src/routes/favorites.ts` (전체 코드)

```ts
import type { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import { articleView } from '../lib/views.js';

interface SlugParams {
  slug: string;
}

/**
 * 즐겨찾기 관련 파생 값을 계산하여 article 객체에 채운 뒤 articleView 를 반환한다.
 * 두 엔드포인트(POST/DELETE)가 공유한다.
 *
 * @param app        FastifyInstance (app.prisma 접근용)
 * @param articleId  대상 article id
 * @param authorId   article 저자 id (following 계산용)
 * @param userId     현재 로그인 사용자 id
 */
async function buildFavoritedArticleView(
  app: FastifyInstance,
  articleId: number,
  authorId: number,
  userId: number,
) {
  // 즐겨찾기 수, 현재 사용자의 즐겨찾기 여부, 저자 팔로우 여부를 병렬 조회
  const [favoritesCount, myFavorite, follow, article] = await Promise.all([
    app.prisma.favorite.count({ where: { articleId } }),
    app.prisma.favorite.findUnique({
      where: { userId_articleId: { userId, articleId } },
    }),
    app.prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: userId, followingId: authorId } },
    }),
    app.prisma.article.findUnique({
      where: { id: articleId },
      include: { author: true, tags: true },
    }),
  ]);

  if (!article) {
    return null;
  }

  const enriched = {
    ...article,
    favorited: Boolean(myFavorite),
    favoritesCount,
    author: {
      ...article.author,
      following: Boolean(follow),
    },
  };

  return articleView(enriched, userId);
}

export default async function (app: FastifyInstance) {
  // POST /api/articles/:slug/favorite — 즐겨찾기 추가 (멱등)
  app.post(
    '/articles/:slug/favorite',
    { preHandler: app.authenticate },
    async (req: FastifyRequest<{ Params: SlugParams }>, reply: FastifyReply) => {
      const { slug } = req.params;
      const userId = req.user!.id;

      const article = await app.prisma.article.findUnique({ where: { slug } });
      if (!article) {
        return reply.code(404).send({ errors: { body: ['article not found'] } });
      }

      await app.prisma.favorite.upsert({
        where: { userId_articleId: { userId, articleId: article.id } },
        create: { userId, articleId: article.id },
        update: {},
      });

      const view = await buildFavoritedArticleView(app, article.id, article.authorId, userId);
      if (!view) {
        return reply.code(404).send({ errors: { body: ['article not found'] } });
      }
      return view;
    },
  );

  // DELETE /api/articles/:slug/favorite — 즐겨찾기 제거 (레코드 없어도 성공)
  app.delete(
    '/articles/:slug/favorite',
    { preHandler: app.authenticate },
    async (req: FastifyRequest<{ Params: SlugParams }>, reply: FastifyReply) => {
      const { slug } = req.params;
      const userId = req.user!.id;

      const article = await app.prisma.article.findUnique({ where: { slug } });
      if (!article) {
        return reply.code(404).send({ errors: { body: ['article not found'] } });
      }

      await app.prisma.favorite.deleteMany({
        where: { userId, articleId: article.id },
      });

      const view = await buildFavoritedArticleView(app, article.id, article.authorId, userId);
      if (!view) {
        return reply.code(404).send({ errors: { body: ['article not found'] } });
      }
      return view;
    },
  );
}
```

### `tests/favorites.test.ts` (전체 코드)

```ts
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { buildApp } from '../src/app.js';
import type { FastifyInstance } from 'fastify';

let app: FastifyInstance;
let token: string;
let slug: string;

before(async () => {
  app = await buildApp();
  await app.ready();

  const uniq = Date.now();

  // 즐겨찾기를 수행할 사용자
  const user = await app.prisma.user.create({
    data: {
      username: `favuser_${uniq}`,
      email: `favuser_${uniq}@example.com`,
      password: 'hashed',
    },
  });

  // 글의 저자
  const author = await app.prisma.user.create({
    data: {
      username: `favauthor_${uniq}`,
      email: `favauthor_${uniq}@example.com`,
      password: 'hashed',
    },
  });

  slug = `fav-article-${uniq}`;
  await app.prisma.article.create({
    data: {
      slug,
      title: 'Fav Test Article',
      description: 'desc',
      body: 'body',
      authorId: author.id,
    },
  });

  token = app.jwt.sign({ id: user.id, username: user.username });
});

after(async () => {
  await app.close();
});

test('POST /articles/:slug/favorite — 즐겨찾기 추가 시 favorited:true, count:1', async () => {
  const res = await app.inject({
    method: 'POST',
    url: `/api/articles/${slug}/favorite`,
    headers: { authorization: `Token ${token}` },
  });

  assert.equal(res.statusCode, 200);
  const body = res.json();
  assert.equal(body.article.favorited, true);
  assert.equal(body.article.favoritesCount, 1);
});

test('POST 재요청 — upsert 멱등성으로 count 1 유지', async () => {
  const res = await app.inject({
    method: 'POST',
    url: `/api/articles/${slug}/favorite`,
    headers: { authorization: `Token ${token}` },
  });

  assert.equal(res.statusCode, 200);
  const body = res.json();
  assert.equal(body.article.favorited, true);
  assert.equal(body.article.favoritesCount, 1);
});

test('DELETE /articles/:slug/favorite — 즐겨찾기 제거 시 favorited:false, count:0', async () => {
  const res = await app.inject({
    method: 'DELETE',
    url: `/api/articles/${slug}/favorite`,
    headers: { authorization: `Token ${token}` },
  });

  assert.equal(res.statusCode, 200);
  const body = res.json();
  assert.equal(body.article.favorited, false);
  assert.equal(body.article.favoritesCount, 0);
});

test('DELETE 재요청 — 레코드 없어도 성공, count 0 유지', async () => {
  const res = await app.inject({
    method: 'DELETE',
    url: `/api/articles/${slug}/favorite`,
    headers: { authorization: `Token ${token}` },
  });

  assert.equal(res.statusCode, 200);
  const body = res.json();
  assert.equal(body.article.favorited, false);
  assert.equal(body.article.favoritesCount, 0);
});

test('POST /articles/:slug/favorite — 없는 slug 는 404', async () => {
  const res = await app.inject({
    method: 'POST',
    url: `/api/articles/no-such-slug-${Date.now()}/favorite`,
    headers: { authorization: `Token ${token}` },
  });

  assert.equal(res.statusCode, 404);
});

test('POST /articles/:slug/favorite — 미인증은 401', async () => {
  const res = await app.inject({
    method: 'POST',
    url: `/api/articles/${slug}/favorite`,
  });

  assert.equal(res.statusCode, 401);
});
```

> 참고: 테스트는 `buildApp()` 이 `src/app.ts` 에서 export 된다고 가정한다(선행 태스크 인프라). 프로젝트의 app 빌더 이름/경로가 다르면 해당 규약에 맞춰 import 만 조정한다. `app.jwt.sign` 페이로드 형태는 `req.user` 계약(`{ id, username }`)과 일치시킨다.

## 완료 기준

- [ ] `src/routes/favorites.ts` 가 위 계약대로 `POST` / `DELETE /articles/:slug/favorite` 두 엔드포인트를 제공한다.
- [ ] 두 엔드포인트 모두 `app.authenticate` preHandler 로 인증을 강제한다(미인증 → 401).
- [ ] 없는 slug 요청은 404 를 반환한다.
- [ ] POST 는 upsert 로 멱등하며, 반복 호출해도 `favoritesCount` 가 중복 증가하지 않는다.
- [ ] DELETE 는 `deleteMany` 로 레코드가 없어도 성공하며 `favorited:false` 를 반환한다.
- [ ] 응답은 `articleView` 형태(`{ article: { ..., favorited, favoritesCount, author: { ..., following } } }`)이다.
- [ ] `favorited` / `favoritesCount` / `following` 계산 로직이 파일 내부 헬퍼로 공유된다.
- [ ] `tests/favorites.test.ts` 의 모든 테스트가 통과한다: `npm test -- favorites`.

